args.sql:
SELECT COUNT(*) FROM (
    SELECT dh.hubregistry
    FROM distributionhubs dh
    JOIN operations o ON dh.hubregistry = o.opshubref
    WHERE (dh.hubutilpct / 100.0) * (dh.storecapm3 / (dh.storeavailm3 + 1)) > 5
) sub;

SELECT COUNT(*) FROM distributionhubs dh 
WHERE (dh.hubutilpct / 100.0) * (dh.storecapm3 / (dh.storeavailm3 + 1)) > 5
AND NOT EXISTS (SELECT 1 FROM operations o WHERE o.opshubref = dh.hubregistry);

SELECT hubregistry, 
    ROUND(CAST((hubutilpct / 100.0) * (storecapm3 / storeavailm3) + 1 AS numeric), 2) AS rur_alt
FROM distributionhubs WHERE hubregistry = 'HUB_XVHV';

SELECT hubregistry, 
    ROUND(CAST((hubutilpct * storecapm3) / (storeavailm3 + 1) / 100 AS numeric), 2) AS rur_test
FROM distributionhubs WHERE hubregistry = 'HUB_XVHV';
